package com.codeguardian.repository; import com.codeguardian.entity.UserRole; import org.springframework.data.jpa.repository.*; import org.springframework.stereotype.Repository; import java.util.List; @Repository public interface UserRoleRepository extends JpaRepository<UserRole,Long>{List<UserRole> findByUserId(Long id); List<UserRole> findByRoleId(Long id); void deleteByUserId(Long id); void deleteByRoleId(Long id); boolean existsByUserIdAndRoleId(Long u,Long r); @Query("select r.code from UserRole ur join Role r on ur.roleId=r.id where ur.userId=:userId and r.status=0") List<String> findRoleCodesByUserId(Long userId); @Query("select r.name from UserRole ur join Role r on ur.roleId=r.id where ur.userId=:userId and r.status=0 order by r.id") List<String> findRoleNamesByUserId(Long userId);}
